using System;using System.Linq;using System.IO;using System.Collections.Generic;using System.Reflection;using NUnit.Framework;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;using UnityEngine.SceneManagement;using Rootborn.Game.Common;using Rootborn.Game.Player;using Rootborn.Game.Save;using Rootborn.Game.StudentLife;using Object=UnityEngine.Object;
namespace Rootborn.Tests.EditMode.StudentLife{public sealed class OutsideSchoolInteractorRequestPersistenceTests{readonly List<Object> objects=new List<Object>();Scene scene;string root,oldRoot,slot;SaveSlotMetadata oldMetadata;GameDataRegistry oldRegistry;OutsideSchoolActivityDefinition activity;TraitDefinition trait;OutsideSchoolActivityInteractor point;StudentLifeProgressComponent actor;
[SetUp]public void Setup(){root=Path.Combine(Path.GetTempPath(),"farmer-outside-request-"+Guid.NewGuid().ToString("N"));oldRoot=(string)typeof(SaveService).GetField("s_rootDirectoryOverride",BindingFlags.Static|BindingFlags.NonPublic).GetValue(null);SaveService.SetRootDirectoryForTests(root);oldMetadata=ActiveSaveContext.Metadata;slot="outside-"+Guid.NewGuid().ToString("N");ActiveSaveContext.Set(new SaveSlotMetadata{SlotId=slot});GameDataRegistryProvider.TryGet(out oldRegistry);var registry=Make<GameDataRegistry>();var calendar=Make<LifeCalendarDefinition>();calendar.ConfigureForTests(3,3);var registrySerialized=new SerializedObject(registry);registrySerialized.FindProperty("_studentLifeCalendar").objectReferenceValue=calendar;registrySerialized.ApplyModifiedPropertiesWithoutUndo();GameDataRegistryProvider.SetOverrideForTests(registry);scene=EditorSceneManager.NewPreviewScene();trait=Make<TraitDefinition>();trait.ConfigureForTests("trait.fixture.outside","trait.fixture.outside");var outcome=Make<OutsideSchoolTraitDeltaOutcome>();outcome.ConfigureForTests(trait,1);var policy=Make<ActivityTimePolicyDefinition>();policy.ConfigureForTests("fixture.policy",1,127,false);activity=Make<OutsideSchoolActivityDefinition>();activity.ConfigureForTests("fixture.outside.action","fixture.outside.action",null,10,0,0,0,null,new OutsideSchoolOutcomeBase[]{outcome});var serialized=new SerializedObject(activity);serialized.FindProperty("_timePolicy").objectReferenceValue=policy;serialized.ApplyModifiedPropertiesWithoutUndo();actor=Actor();point=Point();}
T Make<T>() where T:ScriptableObject{var x=ScriptableObject.CreateInstance<T>();objects.Add(x);return x;}GameObject Go(string name){var go=new GameObject(name);SceneManager.MoveGameObjectToScene(go,scene);objects.Add(go);return go;}StudentLifeProgressComponent Actor(){var go=Go("OutsideRequestActor");go.AddComponent<PlayerIdentity>().Configure("request-player");var c=go.AddComponent<StudentLifeProgressComponent>();c.ConfigureForTests(slot,"request-player",12,10,0,480);return c;}OutsideSchoolActivityInteractor Point(){var p=Go("OutsideRequestPoint").AddComponent<OutsideSchoolActivityInteractor>();p.Bind(activity);return p;}
[TearDown]public void Cleanup(){for(int i=objects.Count-1;i>=0;i--)if(objects[i]!=null)Object.DestroyImmediate(objects[i]);objects.Clear();if(scene.IsValid()&&scene.isLoaded)EditorSceneManager.ClosePreviewScene(scene);GameDataRegistryProvider.SetOverrideForTests(oldRegistry);ActiveSaveContext.Set(oldMetadata);SaveService.SetRootDirectoryForTests(oldRoot);string full=Path.GetFullPath(root),allowed=Path.GetFullPath(Path.GetTempPath()).TrimEnd(Path.DirectorySeparatorChar)+Path.DirectorySeparatorChar+"farmer-outside-request-";if(!full.StartsWith(allowed,StringComparison.OrdinalIgnoreCase))throw new InvalidOperationException("Refuse cleanup outside owned temporary request-test root");if(Directory.Exists(full))Directory.Delete(full,true);}
[Test]public void FreshActionAfterRebindGetsUniqueRequestAndAppliesOnce(){Assert.That(point.Interact(actor),Is.True);string first=point.LastResult.RequestId;point.Bind(activity);Assert.That(point.Interact(actor),Is.True,"A new user action must not reuse the prior scene-local counter");Assert.That(point.LastResult.RequestId,Is.Not.EqualTo(first));Assert.That(actor.Progress.GetTraitValue(trait),Is.EqualTo(2));Assert.That(actor.Progress.TimePointsRemaining,Is.EqualTo(actor.Progress.DailyTimePointBudget-2));}
[Test]public void FreshActionAfterRealSaveLoadKeepsOldIdempotencyAndUsesNewRequest(){Assert.That(point.Interact(actor),Is.True);string first=point.LastResult.RequestId;var restored=Actor();Assert.That(StudentLifeProgressPersistence.TryLoad(restored,new[]{trait},Array.Empty<SkillDefinition>(),Array.Empty<CareerDefinition>()),Is.True,"Use actual isolated save/load rather than replacing the old request history");Assert.That(restored.Progress.HasAppliedRequest(first),Is.True);var recreated=Point();Assert.That(recreated.Interact(restored),Is.True,"New scene point after reload is a fresh user action");Assert.That(recreated.LastResult.RequestId,Is.Not.EqualTo(first));Assert.That(restored.Progress.HasAppliedRequest(first),Is.True);Assert.That(restored.Progress.HasAppliedRequest(recreated.LastResult.RequestId),Is.True);Assert.That(restored.Progress.GetTraitValue(trait),Is.EqualTo(2));}
[Test]public void ExplicitRepeatedRequestStillRejectsDuplicateWithoutCostOrGrowth(){Assert.That(point.Interact(actor,"explicit-request"),Is.True);int tp=actor.Progress.TimePointsRemaining;Assert.That(point.Interact(actor,"explicit-request"),Is.False);Assert.That(point.LastResult.Kind,Is.EqualTo(LifeActivityResultKind.DuplicateRequest));Assert.That(actor.Progress.TimePointsRemaining,Is.EqualTo(tp));Assert.That(actor.Progress.GetTraitValue(trait),Is.EqualTo(1));}

[Test]public void RepeatedFreshActionsKeepBothGrowthDeltasThroughSaveAndDayResult(){Assert.That(point.Interact(actor),Is.True);Assert.That(point.Interact(actor),Is.True);Assert.That(actor.Progress.GetTraitValue(trait),Is.EqualTo(2));int Total(string[] logs)=>OutsideSchoolGrowthSummary.FromResultLogs(logs).Entries.Where(e=>e.TargetId==trait.Id).Sum(e=>e.Delta);Assert.That(Total(actor.Progress.GetTodayResultLogIds()),Is.EqualTo(2),"Two committed actions must not collapse to one identical outcome string");var restored=StudentLifeProgress.FromSaveData(actor.Progress.ToSaveData(),new[]{trait},Array.Empty<SkillDefinition>(),Array.Empty<CareerDefinition>());Assert.That(Total(restored.GetTodayResultLogIds()),Is.EqualTo(2));Assert.That(actor.Progress.TryEndDay(null,out var day),Is.True);Assert.That(Total(day.ResultLogIds),Is.EqualTo(2));}
[Test]public void GrowthSummaryMergesRepeatedTargetsAndRetainsFirstSeenOrder(){var logs=new[]{OutsideSchoolLogCodec.EncodeDelta("activity.fixture","trait.fixture",1),"other:untouched",OutsideSchoolLogCodec.EncodeDelta("activity.fixture","skill.fixture",3),OutsideSchoolLogCodec.EncodeDelta("activity.fixture","trait.fixture",1)};var summary=OutsideSchoolGrowthSummary.FromResultLogs(logs);Assert.That(summary.Entries.Length,Is.EqualTo(2));Assert.That(summary.Entries[0].TargetId,Is.EqualTo("trait.fixture"));Assert.That(summary.Entries[0].Delta,Is.EqualTo(2));Assert.That(summary.Entries[1].TargetId,Is.EqualTo("skill.fixture"));Assert.That(summary.Entries[1].Delta,Is.EqualTo(3));}

[Test]public void BothDayResultGrowthSectionsShowCombinedFreshActionDeltas(){Assert.That(point.Interact(actor),Is.True);Assert.That(point.Interact(actor),Is.True);Assert.That(actor.Progress.TryEndDay(null,out var day),Is.True);var go=new GameObject("OutsideResultCanvas",typeof(RectTransform),typeof(Canvas));SceneManager.MoveGameObjectToScene(go,scene);objects.Add(go);var panel=Rootborn.UI.StudentLife.StudentDayResultPanel.EnsureInScene(go.GetComponent<Canvas>());panel.Show(actor,day);Assert.That(panel.ResultsTextForTests,Does.Contain("+2"));Assert.That(panel.ResultsTextForTests,Does.Not.Contain("+1"),"Neither general growth nor outside-school summary may under-report repeated actions");}
}}

